design('sections',2,'Agree on the code before drawing','Our exercise uses 1 for black and 0 for white, with rows read from the top and left to right.',[g('Send a picture using numbers',[13],'example'),g('A convention belongs to a particular format',[14]),g('Storage is different from recognition',[15]),g('Check the message instructions',[notice],'prompts')])
design('sections',3,'Decode the grid, then read it back','Check every position rather than guessing the shape from a familiar-looking pattern.',[g('Read the three-by-three code',[13]),g('Explain each row',[14]),g('Keep the shape with the flattened list',[15],'example'),g('Connect a sentence to a pixel',[17],'prompts')])
gallery={'type':'gallery','layout':'reading-cards','reading_addition':'week5-connected-reading','cells':[[copy.deepcopy(w['sections'][3]['blocks'][3+i]),copy.deepcopy(w['sections'][3]['blocks'][7+i])] for i in range(4)]};w['sections'][3]['blocks'].append(gallery);idx=len(w['sections'][3]['blocks'])-1
design('sections',4,'Compare the image clues','Use the supplied picture and caption together to distinguish a measurement from an interpretation.',[g('Four cases, paired with their explanations',[idx],'cards'),g('Discuss the confusing pair',[12],'prompts'),g('Keep the pixel boundary clear',[11],'example')])
design('sections',5,'Your image-representation word guide','Use each word to explain what a particular record preserves.',[g('Pixels, grids, channels and resolution',[7]),g('Encoding, arrangement and interpretation',[13]),g('Repair the claim',[9,10],'prompts')],True)
comparison=add('sections',6,image=pic(3));trace=add('sections',6,image=pic(2));change=add('sections',6,image=pic(4))
predict=add('sections',6,'Before checking: change only Badge A’s bottom-left pixel from 0 to 1. Write both complete new rows and the new dark count. Which positions stayed the same? Read your new code back as a picture.')
design('sections',6,'Two badges. Three dark pixels. Different pictures.','A count preserves how many, while a grid preserves where.',[g('The supplied badge convention and rows',[18,20,21],'example'),g('Compare the original arrangements',[comparison]),g('Trace what a count keeps',[trace]),g('Explain why equal counts are insufficient',[26]),g('Predict one changed pixel',[predict],'prompts'),g('Check the changed badge',[change],'example',True),g('Keep the toy format’s limits',[28],'example'),g('Read the position back',[29],'prompts')])
design('sections',7,'Do not confuse more pixels with better evidence','A reconstruction, an interpretation and an instruction make different claims.',[g('More positions do not guarantee a useful image',[11]),g('Separate three levels of claim',[12],'example'),g('Repair the tempting claims',[5,7,9,13],'prompts')])
missing=add('sections',8,'Your W2 message is 1,0,0,1,1,0. Show it as one row of width 6, then as two rows of width 3. In both versions keep the same value order, with 1 black and 0 white. Explain which missing field would tell a receiver which shape to use.')
design('sections',8,'Practise: reconstruct, read back and diagnose','Use a round trip from code to drawing to code to locate a mismatch.',[g('Draw the two-by-three practice grid',[11,12],'example'),g('Now restore a missing dimension',[missing,15,16],'steps'),g('Inspect the input before changing a classifier',[13]),g('Explain and exchange roles',[17]),g('Does 1 always mean black?',[19,20],'prompts'),g('Check the badge position',[22,23,24])])
lab=add('sections',9,'Use width 2 and height 2, with rows 0,1 / 1,0. Here 1 means black and 0 white. Predict the drawing, then decode it on paper and read it back. Keep the numeric grid separate from any name you give its pattern.')
lab2=add('sections',9,'For a declared toy blur, add the four values, divide by 4 and replace every position by that average. On this extended scale, 0.5 is halfway grey. Predict the result before calculating. Then try rows 1,0 / 0,1. Does this blur preserve which diagonal was dark? This is one fully specified averaging rule, not a claim about every real image-blurring method.')
design('sections',9,'Investigate: decode, then apply a toy blur','Use an exact transformation so you can compare a prediction with the actual paper calculation.',[g('Your complete decoding instructions',[lab],'example'),g('Predict and apply the averaging rule',[lab2,6,7,8],'steps'),g('Keep the original, result and limit',[9,12])])
design('sections',10,'Choose a stronger image challenge','Choose one step that tests how well your representation supports a question.',[g('Pick a useful challenge',list(range(4,11)),'prompts')],True)
design('sections',11,'Keep the spatial clues your sorter needs','Choose measurements for the task; do not assume a pixel total describes a shape.',[g('This week’s design decision',[4,14],'example'),g('Plan the representation and checks',[5,6,7,8,9],'prompts'),g('Keep the sensing boundary',[11])])
